"""A ledger of grades."""


class GradeLedger:
    def __init__(self, grades=()):
        self._grades = list(grades)

    def grades(self):
        """Return the grades held (a copy, so callers cannot change the ledger)."""
        return list(self._grades)

    def add(self, grade):
        """Add one grade to the ledger."""
        self.grades().append(grade)

    def total(self):
        """Return the total score of the grades held."""
        return sum(x.score for x in self._grades)

